// Webcam value index — record JAH-GPCS-AIWEBCAM-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"res_mp": 8.3, "fps": 30, "price_usd": 200};
var value = (m.res_mp*m.fps/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-AIWEBCAM-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-AIWEBCAM-000001|' + value.toFixed(2) + ' value index');

